package com.smartfix.communityapp;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.util.*;
@RestController @RequestMapping("/internal/community/v1")
class RemoteThreadApi{
 private final RemoteAnswerService answers;private final JdbcTemplate db;RemoteThreadApi(RemoteAnswerService answers,JdbcTemplate db){this.answers=answers;this.db=db;}
 @GetMapping("/questions/{id}") Map<String,Object> detail(@PathVariable long id,@AuthenticationPrincipal Jwt actor){return answers.detail(id,Long.parseLong(actor.getSubject()),actor.getClaimAsString("role"));}
 @PostMapping("/questions/{id}/answers") Map<String,Object> answer(@PathVariable long id,@RequestBody Map<String,String> request,@RequestHeader("Idempotency-Key")UUID key,@AuthenticationPrincipal Jwt actor){return answers.submit(Long.parseLong(actor.getSubject()),id,request.get("body"),key);}
 @PostMapping("/moderation/events/{id}/retry") Map<String,Boolean> retry(@PathVariable UUID id){int n=db.update("UPDATE community_outbox SET status='PENDING',attempts=0,next_attempt_at=CURRENT_TIMESTAMP,lease_until=NULL,lease_token=NULL WHERE event_id=? AND status='FAILED'",id);if(n!=1)throw new ResponseStatusException(HttpStatus.CONFLICT);return Map.of("queued",true);}
 @PostMapping("/commands/lookup") Map<String,Object> lookup(@RequestBody Map<String,String> body,@AuthenticationPrincipal Jwt actor){if(!"ANSWER".equals(body.get("operation")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);UUID key;try{key=UUID.fromString(body.get("key"));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST);}var rows=db.queryForList("SELECT answer_id,event_id FROM community_answer_commands WHERE actor_id=? AND command_key=?",Long.parseLong(actor.getSubject()),key);if(rows.isEmpty())return Map.of("status","UNKNOWN");var r=rows.get(0);return Map.of("status","COMPLETED","answerId",r.get("answer_id"),"eventId",r.get("event_id").toString());}
}
